// src/App.js
import React from "react";
import { BrowserRouter as Router, Routes, Route, Link, Navigate } from "react-router-dom";
import { AuthProvider } from "./auth";
import ProtectedRoute from "./ProtectedRoute";

import WelcomePage from "./WelcomePage";
import LoginRegister from "./LoginRegister";
import RoleSelection from "./RoleSelection";
import StudentDashboard from "./StudentDashboard";
import NewEntry from "./NewEntry";

export default function App() {
  return (
    <AuthProvider>
      <Router>
        <div className="min-h-screen bg-gray-50 flex flex-col">
          {/* Navbar */}
          <nav className="bg-white shadow p-4 flex justify-between items-center">
            <div className="flex items-center gap-4">
              <Link to="/" className="text-xl font-bold text-indigo-600">📘 E-Diary</Link>
            </div>
            <div className="flex gap-4">
              <Link to="/" className="text-gray-600 hover:text-indigo-600">Home</Link>
              <Link to="/new" className="text-gray-600 hover:text-indigo-600">New Entry</Link>
              <Link to="/dashboard" className="text-gray-600 hover:text-indigo-600">Dashboard</Link>
            </div>
          </nav>

          {/* Main content */}
          <main className="flex-grow p-6">
            <Routes>
              {/* Public routes */}
              <Route path="/" element={<WelcomePage />} />
              <Route path="/login" element={<LoginRegister />} />

              {/* Protected routes */}
              <Route
                path="/role"
                element={
                  <ProtectedRoute>
                    <RoleSelection />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/dashboard"
                element={
                  <ProtectedRoute>
                    <StudentDashboard />
                  </ProtectedRoute>
                }
              />
              <Route
                path="/new"
                element={
                  <ProtectedRoute>
                    <NewEntry />
                  </ProtectedRoute>
                }
              />

              {/* Catch-all: redirect unknown routes to home */}
              <Route path="*" element={<Navigate to="/" />} />
            </Routes>
          </main>

          {/* Footer */}
          <footer className="bg-white border-t p-4 text-center text-sm text-gray-500">
            © {new Date().getFullYear()} Secure E-Diary
          </footer>
        </div>
      </Router>
    </AuthProvider>
  );
}
